{
  "outcome": "escalate",
  "rationale": "We recommend escalating this claim because automated findings indicate it is unclear whether an exclusion applies due to disputed or open facts in the claimant's account. This decision is governed by Section 6, which requires escalation when material facts are open to more than one reasonable reading. The key fact is that the claimant mentioned possible speeding or racing during the incident.",
  "citations": [
    {
      "clause_id": "STD-6.2",
      "quote": "If the documents submitted do not allow the adjuster to determine whether an exclusion applies, because material facts are disputed, missing or open to more than one reasonable reading, the claim must be escalated for further investigation rather than approved or denied on the information available."
    }
  ]
}
